insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_001', 'src_001', 'IT Act 2000', '66C', 'Punishment for identity theft', 'Whoever, fraudulently or dishonestly makes use of the electronic signature, password or any other unique identification feature of any other person, shall be punished with imprisonment of either description for a term which may extend to three years and shall also be liable to fine which may extend to rupees one lakh.', 'Fraudulently using someone else''s password, e-signature or unique ID = up to 3 years jail + up to Rs1 lakh fine.', '2009-10-27', 'verified') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_002', 'src_001', 'IT Act 2000', '66D', 'Punishment for cheating by personation by using computer resource', 'Whoever, by means of any communication device or computer resource cheats by personation, shall be punished with imprisonment of either description for a term which may extend to three years and shall also be liable to fine which may extend to one lakh rupees.', 'Cheating someone online by pretending to be another person/entity = up to 3 years jail + up to Rs1 lakh fine.', '2009-10-27', 'verified') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_003', 'src_002', 'BNS 2023', '318(4)', 'Cheating and dishonestly inducing delivery of property', 'Whoever cheats and thereby dishonestly induces the person deceived to deliver any property to any person, or to make, alter or destroy the whole or any part of a valuable security, or anything which is signed or sealed, and which is capable of being converted into a valuable security, shall be punished with imprisonment of either description for a term which may extend to seven years, and shall also be liable to fine.', 'Cheating that makes a victim hand over money/property = up to 7 years jail + fine. (Replaces old IPC s.420.)', '2024-07-01', 'verified') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_004', 'src_002', 'BNS 2023', '319', 'Cheating by personation', '(1) A person is said to ''cheat by personation'' if he cheats by pretending to be some other person, or by knowingly substituting one person for another, or representing that he or any other person is a person other than he or such other person really is. (2) Whoever cheats by personation shall be punished with imprisonment of either description for a term which may extend to five years, or with fine, or with both.', 'Cheating by pretending to be someone else = up to 5 years jail, or fine, or both. (Replaces old IPC s.416/419.)', '2024-07-01', 'verified') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_005', 'src_003', 'BNSS 2023', '173', 'Information in cognizable cases (FIR / Zero-FIR / e-FIR)', 'Section 173(1) BNSS: information about a cognizable offence, ''irrespective of the area where the offence is committed'', may be given orally or by electronic communication to the officer in charge of a police station, who must register it. This gives statutory backing to the Zero-FIR (register at any station) and to the e-FIR (report electronically; signed within 3 days).', 'You can report a cognizable crime (like fraud) at ANY police station regardless of where it happened (Zero-FIR), and even electronically (e-FIR). Police must register it.', '2024-07-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_006', 'src_004', 'RBI Circular 2017', 'Para 6-7', 'Zero / Limited liability of customer in unauthorised electronic transactions', '[Substance of Paras 6-7 - confirm verbatim text on rbi.org.in] Zero liability where the loss is due to bank fault/system, OR a third-party breach reported to the bank within 3 working days of receiving the transaction communication. Limited liability (Rs5,000/Rs10,000/Rs25,000 by account type) if reported within 4-7 working days. Bank must credit the disputed amount within 10 working days of notification.', 'Tell your bank within 3 working days = zero liability. Report within 4-7 days = limited liability (Rs5k-25k). Bank must credit back within 10 working days.', '2017-07-06', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_007', 'src_008', 'IT Act 2000', '66E', 'Violation of privacy', 'Whoever intentionally or knowingly captures, publishes or transmits the image of a private area of any person without consent, under circumstances violating privacy, shall be punished with imprisonment up to three years or fine not exceeding two lakh rupees, or both.', 'Secretly capturing/sharing private images: up to 3 years or fine up to 2 lakh.', '2009-10-27', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_008', 'src_008', 'IT Act 2000', '67A', 'Sexually explicit material in electronic form', 'Whoever publishes or transmits in electronic form any material containing sexually explicit act shall be punished on first conviction with imprisonment up to five years and fine up to ten lakh rupees.', 'Sharing sexually explicit content online: up to 5 years + up to 10 lakh (first conviction).', '2009-10-27', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_009', 'src_007', 'BNS 2023', '351', 'Criminal intimidation', '(2) Criminal intimidation punishable with imprisonment up to two years, or fine, or both. (3) Threatening death/grievous hurt or imputing unchastity to a woman: up to seven years, or fine, or both.', 'Threats to harm you, your reputation or property; serious threats up to 7 years.', '2024-07-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_010', 'src_007', 'BNS 2023', '79', 'Insult modesty of a woman', 'Whoever, intending to insult the modesty of any woman, utters any word, makes any gesture, exhibits any object or intrudes upon her privacy, shall be punished with simple imprisonment up to three years and fine.', 'Insulting a woman''s modesty or intruding on privacy (incl. online): up to 3 years + fine.', '2024-07-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_011', 'src_002', 'BNS 2023', '319', 'Cheating by personation', '(2) Whoever cheats by personation shall be punished with imprisonment up to five years, or fine, or both.', 'Pretending to be someone else to cheat you: up to 5 years or fine.', '2024-07-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_012', 'src_010', 'BNSS 2023', '35', 'Arrest without warrant; notice of appearance', 'For a cognizable offence punishable with imprisonment less than seven years, the officer shall issue a s.35(3) notice directing the person to appear; arrest is made only if the officer records in writing the reasons for necessity of arrest.', 'For lesser offences (under 7 years) police should usually send a notice, not arrest immediately.', '2024-07-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_013', 'src_010', 'BNSS 2023', '47', 'Grounds of arrest and right to bail', '(1) Every officer arresting without warrant shall forthwith communicate full particulars of the offence or the grounds. (2) For a bailable offence, the person shall be informed of the right to bail and to arrange sureties.', 'If arrested you must be told why at once, and (for bailable offences) about bail.', '2024-07-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_014', 'src_010', 'BNSS 2023', '48', 'Inform relative or friend', 'The officer shall forthwith give information about the arrest and the place of detention to a relative, friend or nominated person.', 'Police must tell a relative/friend of your choice about your arrest and where you are held.', '2024-07-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_015', 'src_010', 'BNSS 2023', '173', 'Information in cognizable cases (FIR/Zero-FIR)', '(1) Information on a cognizable offence, irrespective of the area, may be given orally or electronically and shall be recorded. (4) A person aggrieved by refusal may send the substance in writing by post to the Superintendent of Police.', 'Police must register an FIR anywhere (Zero-FIR); refusal can be escalated to the SP.', '2024-07-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_016', 'src_010', 'BNSS 2023', '175', 'Magistrate power to order investigation', '(3) A Magistrate empowered under section 210 may, on an application supported by affidavit made under s.173(4), order an investigation into a cognizable offence.', 'If police and SP both refuse, a Magistrate can order an FIR/investigation.', '2024-07-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_017', 'src_011', 'PC Act 1988', '7', 'Public servant being bribed', 'A public servant who obtains, accepts or attempts to obtain an undue advantage to perform or forbear a public duty improperly shall be punishable with imprisonment not less than three years extending to seven years and shall also be liable to fine.', 'A government servant demanding a bribe is punishable with 3-7 years jail.', '2018-07-26', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_018', 'src_013', 'MV Act 1988', '194D', 'Penalty for not wearing protective headgear', 'Whoever drives a motor cycle in contravention of section 129 shall be punishable with a fine of one thousand rupees and shall be disqualified for holding licence for a period of three months.', 'No helmet: central fine 1000 + up to 3 months licence disqualification.', '2019-09-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_019', 'src_013', 'MV Act 1988', '194B', 'Use of safety belts and seating of children', '(1) Whoever drives without wearing a safety belt or carries passengers not wearing seat belts shall be punishable with a fine of one thousand rupees.', 'No seatbelt (driver or any passenger): central fine 1000.', '2019-09-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_020', 'src_013', 'MV Act 1988', '185', 'Driving by a drunken person', 'Driving with alcohol exceeding 30 mg per 100 ml of blood: first offence imprisonment up to six months or fine up to ten thousand rupees, or both; second within three years up to two years or fine up to fifteen thousand rupees.', 'Drunk driving: first up to 10000 and/or 6 months; repeat up to 15000 and/or 2 years.', '2019-09-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_021', 'src_013', 'MV Act 1988', '184', 'Driving dangerously', 'Driving in a manner dangerous to the public: first offence imprisonment up to one year or fine of one thousand to five thousand rupees, or both.', 'Dangerous/rash driving: fine 1000-5000 and/or up to 1 year (first offence).', '2019-09-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_022', 'src_013', 'MV Act 1988', '190(2)', 'Using vehicle without valid PUC', 'Driving or permitting a vehicle to be driven in contravention of emission standards: first offence fine of ten thousand rupees.', 'No valid PUC certificate: central fine up to 10000.', '2019-09-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_023', 'src_016', 'Railways Act 1989', '138', 'Excess charge and fare for travelling without proper ticket', 'A passenger detected travelling without a proper pass/ticket or beyond the authorised distance is liable to pay the ordinary single fare for the distance travelled plus an excess charge.', 'Caught without a valid ticket: you pay the fare plus an excess charge.', '1990-07-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_024', 'src_016', 'Railways Act 1989', '137', 'Fraudulently travelling without proper pass or ticket', 'A person travelling with intent to defraud without a proper pass/ticket shall be punishable with imprisonment up to six months, or fine up to one thousand rupees, or both; in the absence of special reasons the fine shall not be less than five hundred rupees.', 'Deliberate ticketless travel: up to 6 months jail or fine up to 1000 (minimum 500).', '1990-07-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_025', 'src_016', 'Railways Act 1989', '162', 'Entering a compartment reserved for women', 'A male passenger who enters or remains in a compartment reserved for women is liable to be removed and to a penalty.', 'A man in a ladies'' compartment can be fined and removed.', '1990-07-01', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_026', 'src_019', 'Maharashtra RTS Act 2015', '9', 'Appeal', '(1) Any eligible person whose application is rejected under s.5(2), or who is not provided the public service within the stipulated time limit, may file an appeal before the First Appellate Authority within thirty days from the date of rejection or expiry of the time limit.', 'Service delayed or wrongly refused: appeal to the First Appellate Authority within 30 days.', '2015-04-28', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_027', 'src_019', 'Maharashtra RTS Act 2015', '10', 'Second appeal', 'A person aggrieved by the decision of the First Appellate Authority may file a second appeal before the Second Appellate Authority within the prescribed period.', 'If the first appeal fails, you can file a second appeal.', '2015-04-28', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_028', 'src_020', 'RTI Act 2005', '19(1)', 'First appeal', 'Any person who does not receive a decision within the time specified in s.7(1), or is aggrieved by a decision of the Public Information Officer, may within thirty days prefer an appeal to an officer senior in rank to the PIO.', 'No RTI reply in 30 days or a bad reply: file a first appeal within 30 days.', '2005-10-12', 'pending_review') on conflict (section_id) do nothing;
insert into public.law_sections (section_id, source_id, law_short_name, section_number, heading, full_text, plain_summary, effective_date, verification_status) values ('sec_029', 'src_020', 'RTI Act 2005', '20', 'Penalties', 'Where the Information Commission finds the PIO refused/delayed without reasonable cause, it shall impose a penalty of two hundred and fifty rupees each day till the application is received or information is furnished, subject to a maximum of twenty-five thousand rupees.', 'A PIO who wrongly delays can be fined 250 rupees/day, up to 25000.', '2005-10-12', 'pending_review') on conflict (section_id) do nothing;
