insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_001', 'cyber', 'Money vanished from my bank/UPI without my approval', 'India', 'An unauthorised transaction debited the user''s bank account or UPI; they did not authorise it.', 'en', 'verified') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_002', 'cyber', 'I was tricked into transferring money (fake bank/officer call)', 'India', 'Someone impersonating a bank, company or official convinced the user to transfer money or share details, and money was lost.', 'en', 'verified') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_003', 'cyber', '''Digital arrest'' / fake police-CBI video call demanding money', 'India', 'Fraudsters posing as police/CBI/customs use a video call to claim the user is under ''digital arrest'' and pressure them to pay.', 'en', 'verified') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_004', 'cyber', 'My bank account got frozen because scam money passed through it', 'India', 'The user''s account is (partially) frozen because funds linked to a fraud were routed through it (possible mule-account flag).', 'en', 'verified') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_005', 'cyber', 'Someone hacked my account / used my credentials', 'India', 'A third party accessed the user''s account, email or wallet using stolen credentials.', 'en', 'verified') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_006', 'cyber', 'Fake investment / trading / ''earn money'' task scam', 'India', 'The user was lured by a fraudulent investment, stock or work-from-home ''task'' scheme and lost money.', 'en', 'verified') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_007', 'cyber', 'I clicked a phishing link / shared an OTP by mistake', 'India', 'The user interacted with a suspicious link or shared a one-time code and fears their account is compromised.', 'en', 'verified') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_008', 'cyber', 'Unauthorised charge on my debit/credit card', 'India', 'A card transaction the user did not make appeared on their statement.', 'en', 'verified') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_009', 'cyber', 'Someone did a SIM swap using my number', 'Maharashtra', 'Your SIM stops working and someone takes over your number to reset OTPs. Report to your operator and 1930 fast.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_010', 'cyber', 'Someone threatens to leak my private photos (sextortion)', 'Maharashtra', 'A person threatens to share private images unless you pay or comply. This is a crime; you can report anonymously.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_011', 'cyber', 'My private photos were shared without consent', 'Maharashtra', 'Someone posted your private images without permission. You can get them taken down and file a complaint.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_012', 'police', 'Police stopped me and are questioning me', 'Maharashtra', 'Ask why you are being stopped and stay calm. Being cooperative and lawful is safest.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_013', 'police', 'I got a police notice to appear (BNSS s.35)', 'Maharashtra', 'For many offences police send a notice instead of arresting. Attend as directed; you can take a lawyer.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_014', 'police', 'I am being arrested', 'Maharashtra', 'You must be told the grounds, allowed to inform a relative/friend, and (for bailable offences) told about bail.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_015', 'police', 'Police are refusing to register my FIR', 'Maharashtra', 'For a cognizable offence police must register an FIR (even a Zero-FIR). If refused, go to the SP then a Magistrate.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_016', 'police', 'A police officer is demanding a bribe', 'Maharashtra', 'Demanding money for official work is a crime. Report to the Anti-Corruption Bureau.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_017', 'police', 'I have been called as a witness', 'Maharashtra', 'You can be required to attend and answer truthfully. Ask for the notice in writing and note the officer''s details.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_018', 'police', 'Someone filed a complaint/FIR against me', 'Maharashtra', 'Stay calm and get legal advice. You have rights during questioning and arrest; do not run or obstruct.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_019', 'traffic', 'Stopped for not wearing a helmet', 'Maharashtra', 'Helmet is mandatory for rider and pillion. Pay via official challan and get a receipt.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_020', 'traffic', 'Stopped for not wearing a seatbelt', 'Maharashtra', 'Seatbelt is mandatory for driver and all passengers. Fine is via official challan.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_021', 'traffic', 'I got an e-challan I think is wrong', 'Maharashtra', 'You can dispute a wrong e-challan online with evidence rather than just paying.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_022', 'traffic', 'A traffic officer is asking for cash on the spot', 'Maharashtra', 'Fines are paid via official challan/receipt or e-challan, not as cash without a receipt.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_023', 'traffic', 'My vehicle was towed/seized', 'Maharashtra', 'Ask where the vehicle is taken and the reason; recover it through the official process and receipt.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_024', 'traffic', 'Stopped for suspected drunk driving', 'Maharashtra', 'Drunk driving is a serious, non-compoundable offence. Cooperate lawfully; never drive intoxicated.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_025', 'traffic', 'I don''t have my licence/insurance/PUC/RC with me', 'Maharashtra', 'You may be fined; digital documents in DigiLocker/mParivahan are generally accepted.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_026', 'railway', 'Caught travelling without a valid ticket', 'Maharashtra', 'You''ll pay the fare plus an excess charge. Take the official receipt from the TC.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_027', 'railway', 'I have the wrong ticket / wrong class', 'Maharashtra', 'You pay the difference plus excess charge; keep the receipt.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_028', 'railway', 'A TC is demanding cash without a receipt', 'Maharashtra', 'Penalties must be paid against an official receipt. A cash demand without one is not proper.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_029', 'railway', 'My belongings were stolen on a Mumbai local', 'Maharashtra', 'Theft on trains/stations is investigated by the GRP (Government Railway Police). File a complaint with them.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_030', 'railway', 'I was harassed/assaulted on a train', 'Maharashtra', 'Call the railway helpline and report to GRP/RPF; crime is handled by GRP.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_031', 'railway', 'UTS/mobile ticket didn''t generate but money was deducted', 'Maharashtra', 'Keep proof of payment; raise a booking-failure-with-debit with the app/support.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_032', 'government_rts', 'My certificate/service application is delayed', 'Maharashtra', 'Notified services have a time limit under the RTS Act. If delayed, you can appeal.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_033', 'government_rts', 'My application was rejected without proper reason', 'Maharashtra', 'A rejection must be in writing with reasons; you can appeal within 30 days.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
insert into public.scenarios (scenario_id, domain, title, jurisdiction, plain_language_summary, language, verification_status) values ('scn_034', 'government_rts', 'The office refuses to accept my application', 'Maharashtra', 'Applications for notified services should be accepted; you can apply online via Aaple Sarkar.', 'en', 'pending_review') on conflict (scenario_id) do nothing;
