insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_001', 'cyber', 'scn_001', 1, 'Immediately call 1930 (national cyber-fraud helpline) to report the fraud so banks can try to freeze/hold the money. Do this within the ''golden hour'' for the best chance of recovery.', 'auth_001', NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_002', 'cyber', 'scn_001', 2, 'Call or message your bank''s official 24x7 fraud number to report the unauthorised transaction IN WRITING and block the card/UPI. Reporting within 3 working days gives you zero liability under RBI rules.', 'auth_004', 'sec_006') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_003', 'cyber', 'scn_001', 3, 'File a complaint on the National Cyber Crime Reporting Portal (cybercrime.gov.in) and save the acknowledgement/complaint number.', 'auth_001', 'sec_005') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_004', 'cyber', 'scn_001', 4, 'If needed, go to the nearest cyber/police station to register an FIR. A Zero-FIR can be filed at any station regardless of where the fraud originated.', 'auth_002', 'sec_005') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_005', 'cyber', 'scn_001', 5, 'If the bank does not resolve or refund within the RBI timeline, escalate to the RBI Integrated Ombudsman via cms.rbi.org.in (generally after 30 days from your bank complaint, or if the bank rejects it).', 'auth_005', 'sec_006') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_006', 'cyber', 'scn_003', 1, 'Understand that no real police, CBI or court arrests people over a video call or asks for payment to ''clear your name''. This is a scam. Do not pay. Disconnect the call.', 'auth_006', NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_007', 'cyber', 'scn_003', 2, 'If you have already paid, call 1930 immediately and file on cybercrime.gov.in to try to freeze the funds.', 'auth_001', 'sec_002') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_008', 'cyber', 'scn_003', 3, 'Report the incident and, if money was lost, register an FIR at the nearest police/cyber station.', 'auth_002', 'sec_005') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_009', 'cyber', 'scn_004', 1, 'Ask your bank IN WRITING for the freeze details - who ordered it, the FIR number, and the legal provision. Under the Jan-2026 MHA/I4C SOP, banks are expected to restrict only the disputed amount, not your entire account.', 'auth_004', NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_010', 'cyber', 'scn_004', 2, 'Submit a written representation with your ID and transaction history to the concerned cyber cell, and get a stamped acknowledgement.', 'auth_001', NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_011', 'cyber', 'scn_004', 3, 'If it is not resolved, seek help from a lawyer and/or escalate the banking-service aspect to the RBI Ombudsman.', 'auth_005', 'sec_006') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_015', 'cyber', 'scn_006', 1, 'Stop all further payments; do not share any OTP/PIN/password.', NULL, NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_016', 'cyber', 'scn_006', 2, 'Call 1930 and file at cybercrime.gov.in with screenshots and records.', 'auth_001', 'sec_001') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_017', 'cyber', 'scn_006', 3, 'Tell your bank to flag the beneficiary accounts; get a reference.', 'auth_004', 'sec_003') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_018', 'cyber', 'scn_006', 4, 'File/allow an FIR under BNS cheating provisions.', 'auth_002', 'sec_002') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_019', 'cyber', 'scn_008', 1, 'Block the affected card via your bank''s official app/helpline.', 'auth_004', 'sec_004') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_020', 'cyber', 'scn_008', 2, 'Report the charge to the bank in writing within 3 working days.', 'auth_004', 'sec_004') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_021', 'cyber', 'scn_008', 3, 'Register at 1930 / cybercrime.gov.in and keep the acknowledgement.', 'auth_001', 'sec_001') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_022', 'cyber', 'scn_008', 4, 'If unresolved in 30 days, escalate to RBI Ombudsman via cms.rbi.org.in.', 'auth_005', 'sec_006') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_023', 'cyber', 'scn_009', 1, 'Contact your operator''s official store/helpline to secure the SIM.', NULL, NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_024', 'cyber', 'scn_009', 2, 'Report number misuse via DoT Sanchar Saathi and 1930 / cybercrime.gov.in.', 'auth_001', 'sec_001') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_025', 'cyber', 'scn_009', 3, 'Alert your bank; change passwords from a trusted device.', 'auth_004', 'sec_003') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_026', 'cyber', 'scn_010', 1, 'Do not pay and do not send more images; keep the messages.', NULL, NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_027', 'cyber', 'scn_010', 2, 'Report at cybercrime.gov.in (Women/Child anonymous option) and call 1930.', 'auth_001', 'sec_008') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_028', 'cyber', 'scn_010', 3, 'File/allow an FIR; police act under BNS s.351/308 and IT Act 67/67A.', 'auth_002', 'sec_009') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_029', 'cyber', 'scn_011', 1, 'Save links/screenshots; report the content to the platform for takedown.', NULL, NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_030', 'cyber', 'scn_011', 2, 'Report at cybercrime.gov.in (Women/Child anonymous) and call 1930.', 'auth_001', 'sec_007') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_031', 'cyber', 'scn_011', 3, 'File/allow an FIR; police act under IT Act 66E/67 and BNS s.79.', 'auth_002', 'sec_010') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_032', 'police', 'scn_015', 1, 'Give your complaint in writing at the police station and ask for a free copy of the FIR.', 'auth_007', 'sec_015') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_033', 'police', 'scn_015', 2, 'If refused, send the substance in writing by post to the Superintendent of Police under BNSS s.173(4).', 'auth_008', 'sec_015') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_034', 'police', 'scn_015', 3, 'If still no action, apply to the jurisdictional Magistrate under BNSS s.175(3) with an affidavit.', 'auth_010', 'sec_016') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_035', 'police', 'scn_016', 1, 'Avoid handing over money if you can; note the demand details and the officer''s name.', NULL, NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_036', 'police', 'scn_016', 2, 'Report the bribe demand to the Anti-Corruption Bureau (toll-free 1064 / WhatsApp +91 9930997700 / acbmaharashtra.gov.in).', 'auth_009', 'sec_017') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_037', 'police', 'scn_014', 1, 'Ask to be told the grounds of arrest and to inform a relative or friend (BNSS s.47/s.48).', 'auth_007', 'sec_013') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_038', 'police', 'scn_014', 2, 'Ask to meet a lawyer; for bailable offences ask about arranging bail.', 'auth_007', 'sec_013') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_039', 'traffic', 'scn_021', 1, 'Do not pay a challan you believe is wrong; gather evidence (photos, timestamp, sale papers).', NULL, NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_040', 'traffic', 'scn_021', 2, 'Raise a grievance at mahatrafficechallan.gov.in (''Apply Grievance Against Challan'') and save the grievance ID.', 'auth_011', NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_041', 'traffic', 'scn_021', 3, 'Alternatively, on echallan.parivahan.gov.in choose ''Pay in Court'' to have it adjudicated.', 'auth_012', NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_042', 'traffic', 'scn_022', 1, 'Ask for an official challan/receipt; note the officer''s name and buckle number.', 'auth_011', NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_043', 'traffic', 'scn_022', 2, 'Report a cash-without-receipt demand to the Anti-Corruption Bureau (1064).', 'auth_009', 'sec_017') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_044', 'traffic', 'scn_023', 1, 'Ask the officer where the vehicle is taken and pay the towing/fine via official receipt to recover it.', 'auth_011', NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_045', 'railway', 'scn_026', 1, 'Pay the fare plus excess charge to the TC and insist on an official receipt.', 'auth_015', 'sec_023') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_046', 'railway', 'scn_028', 1, 'Ask the TC for an official receipt; note the TC''s name/number if none is given.', 'auth_015', 'sec_023') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_047', 'railway', 'scn_028', 2, 'Report a cash-without-receipt demand via the rail helpline 139 or to the RPF (182).', 'auth_014', NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_048', 'railway', 'scn_029', 1, 'Report the theft to the GRP at the nearest railway police post; ask for an FIR.', 'auth_013', 'sec_015') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_049', 'railway', 'scn_030', 1, 'If in danger now, call the RPF security helpline 182 or GRP 1512.', 'auth_014', NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_050', 'railway', 'scn_030', 2, 'File a complaint with the GRP; crime on railways is investigated by the GRP.', 'auth_013', 'sec_015') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_051', 'government_rts', 'scn_032', 1, 'Note your application/acknowledgement number and the stipulated time limit for the service.', 'auth_017', 'sec_026') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_052', 'government_rts', 'scn_032', 2, 'If the time limit has passed, file a first appeal before the First Appellate Authority within 30 days.', 'auth_016', 'sec_026') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_053', 'government_rts', 'scn_032', 3, 'If the first appeal fails, file a second appeal, and then a third appeal to the RTS Commission.', 'auth_017', 'sec_027') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_054', 'government_rts', 'scn_035', 1, 'Do not pay any unofficial amount; note who asked and for what.', NULL, NULL) on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_055', 'government_rts', 'scn_035', 2, 'Report the demand to the Anti-Corruption Bureau (1064).', 'auth_009', 'sec_017') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_056', 'government_rts', 'scn_037', 1, 'File a first appeal within 30 days to an officer senior to the PIO (RTI s.19(1)).', 'auth_018', 'sec_028') on conflict (escalation_id) do nothing;
insert into public.escalation_paths (escalation_id, domain, scenario_id, step_order, step_description, authority_id, legal_basis_section_id) values ('esc_057', 'government_rts', 'scn_037', 2, 'If still unresolved, file a second appeal to the State/Central Information Commission.', 'auth_019', 'sec_029') on conflict (escalation_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_001', 'src_005', NULL, 'scn_001', 'If money has left your bank account or UPI without your approval, act fast. Call the national cyber-fraud helpline 1930 as soon as possible. Reporting within the first hour (the ''golden hour'') gives the best chance of freezing the money before it is withdrawn.', 'cyber', 'India', 'I4C (1930 / NCRP)', 'en', NULL, 'verified', 'https://cybercrime.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_002', 'src_004', 'sec_006', 'scn_001', 'Under RBI rules, if an unauthorised transaction happens and you tell your bank within 3 working days, your liability is zero and the bank must credit the money back within 10 working days. Report to your bank in writing and keep proof of the date and time.', 'cyber', 'India', 'Reserve Bank of India', 'en', '2017-07-06', 'verified', 'https://www.rbi.org.in/commonman/English/Scripts/Notification.aspx?Id=2336') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_003', 'src_004', 'sec_006', 'scn_001', 'If you report an unauthorised bank transaction after 3 days but within 4-7 working days, your loss is capped at a limited amount (Rs5,000 to Rs25,000, depending on account type). Reporting later can increase how much you may have to bear, so report immediately.', 'cyber', 'India', 'Reserve Bank of India', 'en', '2017-07-06', 'verified', 'https://www.rbi.org.in/commonman/English/Scripts/Notification.aspx?Id=2336') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_004', 'src_005', 'sec_005', 'scn_001', 'You can file a cyber-fraud complaint online at cybercrime.gov.in or at any police station. Under the new law, a ''Zero-FIR'' lets you register at any police station regardless of where the fraud happened, and complaints can also be made electronically. Save your complaint/acknowledgement number.', 'cyber', 'India', 'I4C / Police', 'en', '2024-07-01', 'verified', 'https://cybercrime.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_005', 'src_001', 'sec_002', 'scn_002', 'Cheating someone online by pretending to be a bank, company or official is an offence under Section 66D of the IT Act, punishable with up to 3 years in jail and a fine up to Rs1 lakh. If you were tricked into paying, report to 1930 and cybercrime.gov.in right away.', 'cyber', 'India', 'I4C', 'en', '2009-10-27', 'verified', 'https://www.indiacode.nic.in/bitstream/123456789/13116/1/it_act_2000_updated.pdf') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_006', 'src_002', 'sec_003', 'scn_002', 'A scam that dishonestly makes you hand over money can also be prosecuted as cheating under Section 318(4) of the Bharatiya Nyaya Sanhita, 2023 (which replaced the old IPC Section 420), carrying up to 7 years in jail plus a fine.', 'cyber', 'India', 'Police', 'en', '2024-07-01', 'verified', 'https://www.indiacode.nic.in/bitstream/123456789/21069/1/bns__iiitmanipur_english+manipuri_compressed.pdf') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_007', 'src_005', NULL, 'scn_003', '''Digital arrest'' is always a scam. No police officer, CBI or court in India arrests people over a video call or demands money to ''clear your name''. Do not pay, do not share details - end the call. If you already paid, call 1930 immediately.', 'cyber', 'India', 'I4C / Police', 'en', NULL, 'verified', 'https://cybercrime.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_008', 'src_005', NULL, 'scn_004', 'If your account was frozen because fraud money passed through it, ask the bank in writing for the freeze details - the authority that ordered it, the FIR number and the legal provision. Under a Jan-2026 MHA/I4C SOP, banks are expected to restrict only the disputed amount, not your whole account.', 'cyber', 'India', 'I4C / Bank', 'en', '2026-01-01', 'pending_review', 'https://cybercrime.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_009', 'src_001', 'sec_001', 'scn_005', 'If someone accessed your account using your password or credentials, that is identity theft under Section 66C of the IT Act - up to 3 years in jail and a fine up to Rs1 lakh. Change your passwords, turn on two-factor authentication, inform the service/bank, and report at cybercrime.gov.in.', 'cyber', 'India', 'I4C', 'en', '2009-10-27', 'verified', 'https://www.indiacode.nic.in/bitstream/123456789/13116/1/it_act_2000_updated.pdf') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_010', 'src_006', 'sec_006', 'scn_001', 'If your bank does not resolve an unauthorised-transaction complaint or refund you in time, you can escalate to the RBI Integrated Ombudsman. File at cms.rbi.org.in or call 14448, generally after 30 days from your bank complaint or if the bank rejects it. The Ombudsman can order compensation.', 'cyber', 'India', 'RBI Ombudsman', 'en', '2021-11-12', 'verified', 'https://cms.rbi.org.in') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_011', 'src_005', NULL, 'scn_007', 'Never share OTPs, PINs, CVV, passwords or full card numbers with anyone - no genuine bank or official will ask for them. If you clicked a suspicious link or shared a code, immediately change affected passwords, tell your bank to block the card/UPI, and report at 1930 / cybercrime.gov.in.', 'cyber', 'India', 'I4C', 'en', NULL, 'verified', 'https://cybercrime.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_015', 'src_005', NULL, 'scn_006', 'If an investment or ''task'' app promised big returns and now won''t let you withdraw, stop paying. Adding money rarely releases the ''locked'' balance. Save the app link and chats.', 'cyber', 'Maharashtra', 'I4C', 'en', NULL, 'pending_review', 'https://cybercrime.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_016', 'src_005', 'sec_001', 'scn_006', 'Report on cybercrime.gov.in and call 1930. The sooner you report, the better the chance of freezing the money.', 'cyber', 'Maharashtra', 'I4C', 'en', NULL, 'pending_review', 'https://cybercrime.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_017', 'src_004', 'sec_004', 'scn_008', 'For an unauthorised card charge, notify your bank quickly. Under RBI Circular of 6 July 2017, if you notify the bank within three working days of its communication and it was not your fault, your liability is zero and the bank must shadow-reverse the amount within 10 working days.', 'cyber', 'India', 'Bank', 'en', '2017-07-06', 'pending_review', 'https://rbi.org.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_018', 'src_006', 'sec_006', 'scn_008', 'If your bank does not resolve it within 30 days, approach the RBI Ombudsman free of cost at cms.rbi.org.in.', 'cyber', 'India', 'RBI Ombudsman', 'en', NULL, 'pending_review', 'https://cms.rbi.org.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_019', 'src_009', NULL, 'scn_009', 'If your SIM suddenly stops working with no signal, it may be a SIM swap. Contact your operator''s official helpline at once and report at 1930.', 'cyber', 'Maharashtra', 'Maharashtra Cyber', 'en', NULL, 'pending_review', 'https://mhcyber.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_020', 'src_008', 'sec_009', 'scn_010', 'Sextortion is a crime. Do not pay and do not send more photos. Keep the messages and report at cybercrime.gov.in - you can report anonymously in the Women/Child section.', 'cyber', 'India', 'I4C', 'en', NULL, 'pending_review', 'https://cybercrime.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_021', 'src_008', 'sec_007', 'scn_011', 'If your private images are shared without consent, you can ask the platform to remove them and file a complaint. The law (IT Act 66E/67, BNS 79) treats this seriously.', 'cyber', 'India', 'I4C', 'en', NULL, 'pending_review', 'https://cybercrime.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_022', 'src_010', 'sec_012', 'scn_013', 'A police notice under BNSS section 35 asks you to appear. For many offences (under 7 years) this replaces immediate arrest. Attend on the date given and you may bring a lawyer.', 'police', 'Maharashtra', 'Mumbai Police', 'en', '2024-07-01', 'pending_review', 'https://www.indiacode.nic.in/handle/123456789/20063') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_023', 'src_010', 'sec_013', 'scn_014', 'If you are arrested, the officer must tell you at once why. For a bailable offence, they must tell you that you can be released on bail.', 'police', 'Maharashtra', 'Mumbai Police', 'en', '2024-07-01', 'pending_review', 'https://www.indiacode.nic.in/handle/123456789/20063') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_024', 'src_010', 'sec_014', 'scn_014', 'You have the right to have a relative or friend informed about your arrest and where you are held. You can also ask to meet a lawyer.', 'police', 'Maharashtra', 'Mumbai Police', 'en', '2024-07-01', 'pending_review', 'https://www.indiacode.nic.in/handle/123456789/20063') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_025', 'src_010', 'sec_015', 'scn_015', 'For a cognizable offence police must register an FIR - including a Zero-FIR regardless of where it happened. You are entitled to a free copy of the FIR.', 'police', 'Maharashtra', 'Mumbai Police', 'en', '2024-07-01', 'pending_review', 'https://www.indiacode.nic.in/handle/123456789/20063') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_026', 'src_010', 'sec_015', 'scn_015', 'If the police refuse to register your FIR, send your complaint in writing by post to the Superintendent of Police.', 'police', 'Maharashtra', 'SP', 'en', '2024-07-01', 'pending_review', 'https://www.indiacode.nic.in/handle/123456789/20063') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_027', 'src_010', 'sec_016', 'scn_015', 'If the SP also does not act, apply to a Magistrate under BNSS section 175(3), with an affidavit, to order an investigation.', 'police', 'Maharashtra', 'Magistrate', 'en', '2024-07-01', 'pending_review', 'https://www.indiacode.nic.in/handle/123456789/20063') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_028', 'src_012', 'sec_017', 'scn_016', 'If a public servant demands a bribe for official work, it is a crime. Report it to the Maharashtra Anti-Corruption Bureau on toll-free 1064 or at acbmaharashtra.gov.in.', 'police', 'Maharashtra', 'ACB', 'en', NULL, 'pending_review', 'https://acbmaharashtra.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_029', 'src_013', 'sec_018', 'scn_019', 'Helmets are mandatory for both rider and pillion. The MV Act sets a fine of 1000 rupees and possible 3-month licence disqualification; Maharashtra''s notified compounding amount for no-helmet is 500 rupees.', 'traffic', 'Maharashtra', 'Mumbai Traffic Police', 'en', '2019-09-01', 'pending_review', 'https://www.indiacode.nic.in/handle/123456789/1798') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_030', 'src_013', 'sec_019', 'scn_020', 'Seatbelts are mandatory for the driver and every passenger, including the rear. The MV Act fine is 1000 rupees (Maharashtra has notified a lower compounding amount for this personal-safety offence).', 'traffic', 'Maharashtra', 'Mumbai Traffic Police', 'en', '2019-09-01', 'pending_review', 'https://www.indiacode.nic.in/handle/123456789/1798') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_031', 'src_014', NULL, 'scn_021', 'If you believe an e-challan is wrong, do not just pay it. Raise a grievance at mahatrafficechallan.gov.in with your evidence and keep the grievance ID.', 'traffic', 'Maharashtra', 'Mumbai Traffic Police', 'en', NULL, 'pending_review', 'https://mahatrafficechallan.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_032', 'src_015', NULL, 'scn_021', 'On the national portal echallan.parivahan.gov.in you can choose ''Pay in Court'' to contest a challan before a court instead of paying it.', 'traffic', 'India', 'MoRTH', 'en', NULL, 'pending_review', 'https://echallan.parivahan.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_033', 'src_013', 'sec_020', 'scn_024', 'Drunk driving is serious: first offence up to 10000 rupees and/or 6 months jail. It is non-compoundable and can void your insurance. Never drive after drinking.', 'traffic', 'India', 'Mumbai Traffic Police', 'en', '2019-09-01', 'pending_review', 'https://www.indiacode.nic.in/handle/123456789/1798') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_034', 'src_013', NULL, 'scn_025', 'MoRTH has advised states to accept your licence, RC, insurance and PUC in electronic form via DigiLocker or mParivahan as valid under the Motor Vehicles Act, so carry them on your phone.', 'traffic', 'Maharashtra', 'Mumbai Traffic Police', 'en', NULL, 'pending_review', 'https://echallan.parivahan.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_035', 'src_016', 'sec_023', 'scn_026', 'If you are caught without a valid ticket, you pay the normal fare for the distance plus an excess charge. Always take the official receipt from the ticket examiner.', 'railway', 'Maharashtra', 'GRP', 'en', '1990-07-01', 'pending_review', 'https://www.indiacode.nic.in/handle/123456789/1908') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_036', 'src_016', 'sec_024', 'scn_026', 'Deliberately travelling ticketless can be punished under Railways Act section 137 with up to 6 months jail or a fine up to 1000 rupees (minimum 500).', 'railway', 'India', 'GRP', 'en', '2024-03-01', 'pending_review', 'https://www.indiacode.nic.in/handle/123456789/1908') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_037', 'src_018', NULL, 'scn_029', 'Theft and crime on Mumbai local trains and stations are investigated by the Government Railway Police (GRP), not the RPF. Report to the nearest GRP post.', 'railway', 'Maharashtra', 'GRP', 'en', NULL, 'pending_review', 'https://indianrailways.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_038', 'src_018', NULL, 'scn_030', 'If you are being harassed or are in danger on a train, call the RPF security helpline 182 or the railway helpline 139. For registering a crime, the GRP handles the case.', 'railway', 'Maharashtra', 'RPF', 'en', NULL, 'pending_review', 'https://indianrailways.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_039', 'src_016', 'sec_025', 'scn_030', 'A man travelling in a ladies'' compartment can be fined and removed. Women commuters can call the GRP helpline 1512 for help.', 'railway', 'Maharashtra', 'GRP', 'en', '1990-07-01', 'pending_review', 'https://www.indiacode.nic.in/handle/123456789/1908') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_040', 'src_019', 'sec_026', 'scn_032', 'Under the Maharashtra Right to Public Services Act 2015, notified services must be delivered within a set time limit. If they are late, you can appeal to the First Appellate Authority within 30 days.', 'government_rts', 'Maharashtra', 'First Appellate Authority', 'en', '2015-04-28', 'pending_review', 'https://www.indiacode.nic.in/bitstream/123456789/19708/1/201531.pdf') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_041', 'src_019', 'sec_026', 'scn_033', 'A rejection of your application must be in writing with reasons and must tell you how to appeal. You can challenge an unfair rejection within 30 days.', 'government_rts', 'Maharashtra', 'First Appellate Authority', 'en', '2015-04-28', 'pending_review', 'https://www.indiacode.nic.in/bitstream/123456789/19708/1/201531.pdf') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_042', 'src_021', NULL, 'scn_034', 'Many Maharashtra services can be applied for online at Aaple Sarkar (aaplesarkar.mahaonline.gov.in), so you do not depend on one office accepting a paper form.', 'government_rts', 'Maharashtra', 'RTS Commission', 'en', NULL, 'pending_review', 'https://aaplesarkar.mahaonline.gov.in/') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_043', 'src_020', 'sec_028', 'scn_037', 'If you get no RTI reply within 30 days or a poor reply, you can file a first appeal within 30 days to an officer senior to the Public Information Officer.', 'government_rts', 'India', 'First Appellate Authority', 'en', '2005-10-12', 'pending_review', 'https://www.indiacode.nic.in/handle/123456789/1362') on conflict (chunk_id) do nothing;
insert into public.document_chunks (chunk_id, source_id, law_section_id, scenario_id, content, domain, jurisdiction, authority, language, effective_date, verification_status, source_url) values ('chunk_044', 'src_020', 'sec_029', 'scn_037', 'If the appeal fails, you can approach the Information Commission, which can fine the officer 250 rupees a day (up to a maximum of 25000) for wrongful delay.', 'government_rts', 'India', 'Information Commission', 'en', '2005-10-12', 'pending_review', 'https://www.indiacode.nic.in/handle/123456789/1362') on conflict (chunk_id) do nothing;
